import { Novu } from "@novu/api";
 const novu = new Novu({ secretKey: process.env.NOVU_SECRET_KEY });

 app.post("/webhooks/cal", async (req, res) => {
  const { triggerEvent, payload } = req.body; // validar antes el encabezado x-cal-signature-256
  if (triggerEvent === "BOOKING_CREATED") {
  const paciente = payload.attendees[0];
  await novu.trigger({
  workflowId: "recordatorio-cita",
  to: { subscriberId: paciente.email, email: paciente.email },
  payload: { inicio: payload.startTime, titulo: payload.title },
  });
  }
  res.sendStatus(200);
 });

import { AccessToken } from "livekit-server-sdk";

 // req.user viene del middleware que valida el token de Keycloak
 app.get("/video/token/:citaId", async (req, res) => {
  const at = new AccessToken(process.env.LIVEKIT_API_KEY,
  process.env.LIVEKIT_API_SECRET, {
  identity: req.user.sub,
  name: req.user.name,
  });
  at.addGrant({ roomJoin: true, room: `cita-${req.params.citaId}` });
  res.json({ token: await at.toJwt() });
 });

import Typesense from "npm:typesense";
 const ts = new Typesense.Client({
  nodes: [{ host: "typesense", port: 8108, protocol: "http" }],
  apiKey: Deno.env.get("TYPESENSE_ADMIN_KEY"),
 });

 Deno.serve(async (req) => {
  const { type, record, old_record } = await req.json();
  if (type === "DELETE") {
  await ts.collections("freelancers").documents(String(old_record.id)).delete();
  } else {
  await ts.collections("freelancers").documents().upsert({
  id: String(record.id), nombre: record.nombre,
  habilidades: record.habilidades, tarifa: record.tarifa });
  }
  return new Response("ok");
 });

