app.post("/webhooks/strapi", async (req, res) => {
  const { event, model, entry } = req.body;
  if (model !== "alojamiento") return res.sendStatus(204);
  if (event === "entry.unpublish" || event === "entry.delete") {
  await ts.collections("alojamientos").documents(entry.documentId).delete();
  } else {
  await ts.collections("alojamientos").documents().upsert({
  id: entry.documentId, nombre: entry.nombre,
  precio: entry.precio, ubicacion: [entry.lat, entry.lon] });
  }
  res.sendStatus(200);
 });

