const { createClient, id } = require("tigerbeetle-node");
 const tb = createClient({ cluster_id: 0n, replica_addresses: ["3000"] });

 app.post("/webhooks/hyperswitch", async (req, res) => {
  const ev = req.body; // validar la firma del webhook antes
  if (ev.event_type === "payment_succeeded") {
  // Devuelve un resultado por transferencia (created, exists o failed): revisar su estado
  const resultados = await tb.createTransfers([{
  // con id() cada reintento del webhook crearía otra transferencia: en producción,
  // usar un ID fijo derivado del pago (por ejemplo, de payment_id) para que el reintento devuelva exists
  id: id(), debit_account_id: cuentaCliente(ev),
  credit_account_id: CUENTA_COMERCIO,
  amount: BigInt(ev.content.object.amount), ledger: 1, code: 1,
  pending_id: 0n, user_data_128: 0n, user_data_64: 0n,
  user_data_32: 0, timeout: 0, flags: 0, timestamp: 0n }]);
  // si el resultado es failed, responder con error para que Hyperswitch reintente
  }
  res.sendStatus(200);
 });

