# 1) SeaweedFS con su gateway compatible con S3 (Docker)
  docker run -p 8333:8333 chrislusf/seaweedfs server -s3

  # 2) Crear el bucket con la CLI de AWS apuntando a SeaweedFS
  aws --endpoint-url http://localhost:8333 s3 mb s3://strapi-media

  # 3) Instalar el proveedor oficial en Strapi
  npm install @strapi/provider-upload-aws-s3 --save

  // 4) config/plugins.js (Strapi): credenciales en variables de entorno
  module.exports = ({ env }) => ({
  upload: {
  config: {
  provider: 'aws-s3',
  providerOptions: {
  s3Options: {
  credentials: {
  accessKeyId: env('S3_ACCESS_KEY'),
  secretAccessKey: env('S3_SECRET_KEY'),
  },
  endpoint: env('S3_ENDPOINT'), // por ejemplo, http://seaweedfs:8333
  region: env('S3_REGION', 'us-east-1'),
  forcePathStyle: true,
  requestChecksumCalculation: 'WHEN_REQUIRED', // recomendado por SeaweedFS
  responseChecksumValidation: 'WHEN_REQUIRED',
  params: { Bucket: env('S3_BUCKET') },
  },
  },
  },
  },
  });

// Página de login (Node.js): Kratos autentica; Hydra emite los tokens
 const challenge = req.query.login_challenge;
 const sesion = await fetch("http://kratos:4433/sessions/whoami", {
  headers: { cookie: req.headers.cookie },
 }).then((r) => r.json());
 if (!sesion?.identity) return res.redirect("/self-service/login/browser");

 const { redirect_to } = await fetch(
  `http://hydra:4445/admin/oauth2/auth/requests/login/accept?login_challenge=${challenge}`,
  { method: "PUT", headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ subject: sesion.identity.id, remember: true }) }
 ).then((r) => r.json());
 res.redirect(redirect_to);

