// app/api/documentos/[id]/route.ts (Next.js)
 import { headers } from "next/headers";
 import { auth } from "@/lib/auth"; // configuración de Better Auth
 import { OpenFgaClient } from "@openfga/sdk";

 const fga = new OpenFgaClient({
  apiUrl: process.env.FGA_API_URL,
  storeId: process.env.FGA_STORE_ID,
 });

 export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const sesion = await auth.api.getSession({ headers: await headers() });
  if (!sesion) return new Response("No autenticado", { status: 401 });

  const { allowed } = await fga.check({
  user: `user:${sesion.user.id}`, relation: "viewer", object: `document:${id}`,
  });
  if (!allowed) return new Response("Sin permiso", { status: 403 });
  // ...leer y devolver el documento
 }

import { GRPC } from "@cerbos/grpc";
 import { PrismaClient } from "@prisma/client";
 import { queryPlanToPrisma, PlanKind } from "@cerbos/orm-prisma";

 const cerbos = new GRPC("cerbos:3593", { tls: false });
 const prisma = new PrismaClient();

 export async function listarExpedientes(usuario: { id: string; roles: string[]; area: string }) {
  const plan = await cerbos.planResources({
  principal: { id: usuario.id, roles: usuario.roles, attr: { area: usuario.area } },
  resource: { kind: "expediente" },
  action: "ver",
  });
  const r = queryPlanToPrisma({
  queryPlan: plan,
  mapper: {
  "request.resource.attr.area": { field: "area" },
  "request.resource.attr.abogadoId": { field: "abogadoId" },
  },
  });
  if (r.kind === PlanKind.ALWAYS_DENIED) return [];
  return prisma.expediente.findMany({ where: r.filters });
 }

