 ALTER TABLE propiedades ADD COLUMN ubicacion geography(Point, 4326);
 UPDATE propiedades SET ubicacion = ST_SetSRID(ST_MakePoint(longitud, latitud), 4326)::geography;
 CREATE INDEX propiedades_ubicacion_idx ON propiedades USING GIST (ubicacion);

 -- Propiedades a menos de 2 km del punto buscado, de la más cercana a la más lejana
 SELECT id, titulo,
  ST_Distance(ubicacion, ST_MakePoint(-70.65, -33.45)::geography) AS metros
 FROM propiedades
 WHERE ST_DWithin(ubicacion, ST_MakePoint(-70.65, -33.45)::geography, 2000)
 ORDER BY metros
 LIMIT 50;

