import { list } from "@keystone-6/core";
 import { text } from "@keystone-6/core/fields";
 import { allowAll } from "@keystone-6/core/access";

 const MANTICORE = "http://manticore:9308";
 const enviar = (ruta: string, cuerpo: object) =>
  fetch(`${MANTICORE}/${ruta}`, { method: "POST", headers: { "Content-Type": "application/json" },
  body: JSON.stringify(cuerpo) });

 export const Articulo = list({
  access: allowAll,
  db: { idField: { kind: "autoincrement" } },
  fields: { titulo: text(), cuerpo: text({ ui: { displayMode: "textarea" } }) },
  hooks: {
  afterOperation: async ({ operation, item, originalItem }) => {
  if (operation === "delete") {
  await enviar("delete", { index: "articulos", id: Number(originalItem.id) });
  } else {
  await enviar("replace", { index: "articulos", id: Number(item.id),
  doc: { titulo: item.titulo, cuerpo: item.cuerpo } });
  }
  },
  },
 });

import pendulum, requests
 from airflow.sdk import dag, task # Airflow 3 (en Airflow 2: from airflow.decorators import dag, task)

 @dag(schedule="0 3 * * *", catchup=False,
  start_date=pendulum.datetime(2026, 10, 1, tz="America/Santiago"))
 def reindexar_expedientes():

  @task(retries=3)
  def extraer() -> list[dict]:
  return obtener_expedientes_modificados() # consulta a la base del estudio

  @task(retries=3)
  def indexar(docs: list[dict]):
  r = requests.post("http://solr:8983/solr/expedientes/update",
  params={"commit": "true"}, json=docs, timeout=120)
  r.raise_for_status()

  indexar(extraer())

 reindexar_expedientes()

