import flagsmith from "@flagsmith/flagsmith";
 import { FlagsmithProvider, useFlags } from "@flagsmith/flagsmith/react";
 import { Alert, Button, ChakraProvider, defaultSystem } from "@chakra-ui/react";

 export default function App() {
  return (
  <FlagsmithProvider flagsmith={flagsmith} options={{
  environmentID: process.env.NEXT_PUBLIC_FLAGSMITH_ENV_ID!,
  api: "https://flags.ejemplo.com/api/v1/",
  }}>
  <ChakraProvider value={defaultSystem}><Inicio /></ChakraProvider>
  </FlagsmithProvider>
  );
 }

 function Inicio() {
  const { banner_promocion, nuevo_checkout } = useFlags(["banner_promocion", "nuevo_checkout"]);
  return (
  <>
  {banner_promocion.enabled && (
  <Alert.Root status="info"><Alert.Title>{String(banner_promocion.value)}</Alert.Title></Alert.Root>
  )}
  <Button colorPalette={nuevo_checkout.enabled ? "purple" : "gray"}>Pagar</Button>
  </>
  );
 }

import * as echarts from "echarts";

 const fin = Math.floor(Date.now() / 1000), inicio = fin - 3600;
 const q = encodeURIComponent('sum(rate(http_requests_total{job="api"}[5m]))');
 const { data } = await fetch(
  `/prometheus/api/v1/query_range?query=${q}&start=${inicio}&end=${fin}&step=60`
 ).then((r) => r.json());
 const puntos = data.result[0]?.values.map(([t, v]) => [t * 1000, Number(v)]) ?? [];

 const grafico = echarts.init(document.getElementById("grafico"));
 grafico.setOption({
  tooltip: { trigger: "axis" },
  xAxis: { type: "time" },
  yAxis: { type: "value", name: "solicitudes/s" },
  series: [{ type: "line", name: "Solicitudes por segundo", data: puntos, showSymbol: false }],
 });

