 const tema = {
  ...defaultTheme,
  palette: { primary: { main: "#1e3a8a" }, secondary: { main: "#f59e0b" } },
  typography: { fontFamily: "Inter, sans-serif" },
 };

 const ListaPedidos = () => (
  <List>
  <Datagrid rowClick="edit">
  <TextField source="id" /><TextField source="cliente" /><DateField source="fecha" />
  </Datagrid>
  </List>
 );

 export default function App() {
  return (
  <Admin dataProvider={simpleRestProvider(import.meta.env.VITE_API_URL)} theme={tema}>
  <Resource name="pedidos" list={ListaPedidos} />
  </Admin>
  );
 }

