 // Consulta "login" (POST /login), cuerpo JSON:
 { "username": "{{secrets.OPENBOXES_USER}}",
  "password": "{{secrets.OPENBOXES_PASSWORD}}",
  "location": "<id_bodega>" }

 // Consulta "despachos" (GET /stockMovements?direction=OUTBOUND&max=50)
 // Transformación (JavaScript) para la tabla:
 return data.data.map((m) => ({
  id: m.id,
  destino: m.destination?.name,
  estado: m.status,
  solicitado: m.dateRequested,
 }));

const r = await fetch("http://graphhopper:8989/route", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({
  profile: "car",
  points: [[-70.6506, -33.4372], [-70.6005, -33.4172]], // [longitud, latitud]
  points_encoded: false,
  locale: "es",
  }),
 });
 const ruta = (await r.json()).paths[0];

 map.addSource("ruta", { type: "geojson", data: { type: "Feature", properties: {}, geometry: ruta.points } });
 map.addLayer({ id: "ruta", type: "line", source: "ruta",
  paint: { "line-color": "#2563eb", "line-width": 5 } });
 console.log(`${(ruta.distance / 1000).toFixed(1)} km · ${Math.round(ruta.time / 60000)} min`);

